from pathlib import Path
import math
import resvg_py

OUT = Path(__file__).parent
W, H = 1120, 800
slides = [3.1, 6, 9]
gaps = [3, 3, 10, 3, 3, 13, 3, 3, 10, 3]
parts = [f'''<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}">
<defs><linearGradient id="paper" x2="0" y2="1"><stop stop-color="#f4f1e8"/><stop offset="1" stop-color="#e9e5db"/></linearGradient>
<linearGradient id="pane" x2="0" y2="1"><stop stop-color="#344b5e"/><stop offset=".6" stop-color="#73868b"/><stop offset="1" stop-color="#435b68"/></linearGradient></defs>
<rect width="100%" height="100%" fill="url(#paper)"/>
<text x="68" y="52" fill="#66777b" font-family="Arial,sans-serif" font-size="11" letter-spacing="2.8">THE MOVING VIEWPOINT Â· DEPTH STUDIES</text>
<text x="68" y="91" fill="#263c4c" font-family="Georgia,serif" font-size="31">How far should one sheet slip past another?</text>''']

for r, slide in enumerate(slides):
    y0=176+r*195
    pane_w,pane_h=64,132
    total=11*pane_w+sum(gaps)
    x0=(W-total)/2
    parts.append(f'<text x="68" y="{y0}" fill="#263c4c" font-family="Georgia,serif" font-size="18">{slide:g} SVG units per pane</text>')
    parts.append(f'<text x="1050" y="{y0}" text-anchor="end" fill="#66777b" font-family="Arial,sans-serif" font-size="11">same left view Â· same interval</text>')
    x=x0
    for i in range(11):
        depth=i-5
        # A leftward walk shifts farther sheets back toward the row's center.
        xx=x-depth*slide
        yy=y0+18+abs(depth)*.7+depth*2.5
        parts.append(f'<rect x="{xx:.2f}" y="{yy:.2f}" width="{pane_w}" height="{pane_h}" fill="url(#pane)" fill-opacity=".76" stroke="#eef0e8" stroke-opacity=".8" stroke-width="1.1"/>')
        bend=math.sin(i*.62)*2
        hy=yy+65+bend
        parts.append(f'<path d="M{xx-2:.2f} {hy:.2f} Q{xx+30:.2f} {hy-5:.2f} {xx+pane_w+2:.2f} {hy+1:.2f}" fill="none" stroke="#dfb08c" stroke-width="2.6"/>')
        parts.append(f'<path d="M{xx+9:.2f} {yy+39:.2f} Q{xx+30:.2f} {yy+33:.2f} {xx+52:.2f} {yy+40:.2f}" fill="none" stroke="#d0d2c9" stroke-opacity=".5" stroke-width="1.8"/>')
        x += pane_w + (gaps[i] if i<10 else 0)
    parts.append(f'<path d="M100 {y0+164}H1020" stroke="#c7c5bc" stroke-width="1"/>')

parts.append('''<text x="68" y="770" fill="#66777b" font-family="Arial,sans-serif" font-size="11" letter-spacing="1.2">DRAWING UNITS ONLY Â· NOT A PHYSICAL MEASUREMENT</text></svg>''')
svg="".join(parts)
(OUT/'parallax-studies.svg').write_text(svg,encoding='utf-8')
(OUT/'parallax-studies.png').write_bytes(bytes(resvg_py.svg_to_bytes(svg_string=svg)))

